
local uis=[==[]==]
local syh=
(function(...)
local fbgfi={244,244,49,142,71,113,66,40,134,236,211,44,194,175,26,40,28,59,107,191,124,176,226,148,220,207,158,212,156}
local lck=bit32 or bit
local sjk=lck.bxor
for kjoq=1,#fbgfi do fbgfi[kjoq]=sjk(fbgfi[kjoq],(181*kjoq+166)%256) end
local yi="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local mk={}
for eecj=1,#yi do mk[yi:byte(eecj)]=eecj-1 end
local function mmm(str)
  local R={} local acc,nb=0,0
  for qm=1,#str do
    local v=mk[str:byte(qm)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function rs(key,data)
  local S={} for qj=0,255 do S[qj]=qj end
  local j=0
  for wef=0,255 do
    j=(j+S[wef]+key[(wef%#key)+1])%256
    S[wef],S[j]=S[j],S[wef]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(sjk(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=rs(fbgfi,mmm(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local vh=nf()
return function(big) return vh(big) end
end)(...)

return syh(uis)
